// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GroupBuySeat) predicate.GroupBuySeat {
	return predicate.GroupBuySeat(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GroupBuySeat) predicate.GroupBuySeat {
	return predicate.GroupBuySeat(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GroupBuySeat) predicate.GroupBuySeat {
	return predicate.GroupBuySeat(sql.NotPredicates(p))
}
